import java.io.InputStreamReader

fun main() {
    var ans = 0
    var met = false
    val br = BufferedReader(InputStreamReader(System.`in`))
    var line: String?
    while (br.readLine().also { line = it } != null) {
        val input = line!!
        if (input == "BBBBBBBB") {
            ans++
        } else if (!met) {
            val temp = Regex("B").findAll(input).count()
            ans += temp
            met = true
        }
    }
    println(ans)
}
